import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';
const site=process.cwd(),ts=createRequire(site+'/package.json')('typescript'),phase=process.env.VM_NATIVE_DISCLOSURE_PHASE;assert(/^types(?:-v\d+)?$/.test(phase));const config=site+'/tsconfig.json',loaded=ts.readConfigFile(config,ts.sys.readFile);assert(!loaded.error);const parsed=ts.parseJsonConfigFileContent(loaded.config,ts.sys,site);assert.equal(parsed.errors.length,0);assert(parsed.options.strict);const roots=['components/NativeDisclosure.tsx','components/StudioNavigation.tsx','components/AtlasWorkspaceNavigation.tsx','app/workspace/page.tsx'].map(p=>site+'/'+p),ambient=parsed.fileNames.filter(p=>p.endsWith('.d.ts'));assert.equal(ambient.length,6);const program=ts.createProgram([...roots,...ambient],{...parsed.options,noEmit:true,incremental:false}),diagnostics=ts.getPreEmitDiagnostics(program),sha=b=>createHash('sha256').update(b).digest('hex');const result={at:new Date().toISOString(),roots,ambient,config,configSha256:sha(fs.readFileSync(config)),configuredCompilerOptions:parsed.options,sourceFiles:program.getSourceFiles().map(f=>({path:path.resolve(f.fileName),sha256:sha(fs.readFileSync(f.fileName))})),diagnostics:diagnostics.map(d=>({code:d.code,path:d.file?.fileName,start:d.start,message:ts.flattenDiagnosticMessageText(d.messageText,'\n')})),actualStrictConfiguration:true,moduleSubstitutions:false,fullProjectTypesPassed:false};fs.writeFileSync('../checks/'+phase+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});if(diagnostics.length)console.error(ts.formatDiagnosticsWithColorAndContext(diagnostics,{getCurrentDirectory:()=>site,getCanonicalFileName:f=>f,getNewLine:()=> '\n'}));console.log(JSON.stringify({roots:roots.length,ambient:ambient.length,files:result.sourceFiles.length,diagnostics:diagnostics.length}));assert.equal(diagnostics.length,0);
